script:
frappe.ui.form.on('Stock Entry', {
    onload: function(frm) {
        if (frm.doc.docstatus !== 0) return;  // only drafts - don't rewrite submitted/cancelled entries

        // ✅ Default set
        if (!frm.doc.stock_entry_type) {
            frm.set_value('stock_entry_type', 'Material Issue');
        }

        // ✅ Lock field (user change na kare)
        frm.set_df_property('stock_entry_type', 'read_only', 1);
    },

    refresh: function(frm) {
        if (frm.doc.docstatus !== 0) return;  // only drafts - don't rewrite submitted/cancelled entries

        // Ensure always Material Issue
        frm.set_value('stock_entry_type', 'Material Issue');
        frm.set_df_property('stock_entry_type', 'read_only', 1);
    }
});

frappe.ui.form.on('Stock Entry', {

    company: function(frm) {
        set_default_warehouse_stock(frm);
        set_cost_center_stock(frm);
    },

    onload: function(frm) {
        if (frm.doc.company) {
            set_default_warehouse_stock(frm);
            set_cost_center_stock(frm);
        }
    }
});


// 🔥 Item select hone par
frappe.ui.form.on('Stock Entry Detail', {

    item_code: function(frm, cdt, cdn) {
        set_default_warehouse_stock(frm);
    }
});


// 🔥 Warehouse logic (Item Defaults se)
function set_default_warehouse_stock(frm) {
        if (frm.doc.docstatus !== 0) return;  // only drafts - don't rewrite submitted/cancelled entries

    if (!frm.doc.company) return;

    let first_item = (frm.doc.items || [])[0];

    if (!first_item || !first_item.item_code) return;

    frappe.db.get_doc('Item', first_item.item_code).then(item => {

        let match = (item.item_defaults || []).find(d =>
            d.company === frm.doc.company
        );

        if (match && match.default_warehouse) {

            let warehouse = match.default_warehouse;

            // ✅ Child table me set
            (frm.doc.items || []).forEach(row => {
                row.s_warehouse = warehouse;
            });

            // ✅ 🔥 Parent field me bhi set (IMPORTANT)
            frm.set_value('from_warehouse', warehouse);

            frm.refresh_field('items');
        }
    });
}


// 🔥 COST CENTER FIX
function set_cost_center_stock(frm) {
        if (frm.doc.docstatus !== 0) return;  // only drafts - don't rewrite submitted/cancelled entries

    if (!frm.doc.company) return;

    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Company",
            filters: { name: frm.doc.company },
            fieldname: ["cost_center"]
        },
        async: false,
        callback: function(r) {

            if (r.message && r.message.cost_center) {

                (frm.doc.items || []).forEach(row => {
                    row.cost_center = r.message.cost_center;
                });

                frm.refresh_field('items');
            }
        }
    });
}

frappe.ui.form.on('Stock Entry', {

    refresh: function(frm) {
        update_parent_warehouse(frm);
    }

});


// 🔹 Child table trigger
frappe.ui.form.on('Stock Entry Detail', {

    s_warehouse: function(frm, cdt, cdn) {
        update_parent_warehouse(frm);
    },

    items_add: function(frm) {
        update_parent_warehouse(frm);
    }

});


// 🔹 Main function
function update_parent_warehouse(frm) {
        if (frm.doc.docstatus !== 0) return;  // only drafts - don't rewrite submitted/cancelled entries

    if (frm.doc.stock_entry_type !== "Material Issue") return;

    let warehouses = frm.doc.items
        .map(row => row.s_warehouse)
        .filter(w => w);

    if (warehouses.length === 0) return;

    let unique = [...new Set(warehouses)];

    // ✅ Agar sab rows same hai
    if (unique.length === 1) {
        frm.set_value("from_warehouse", unique[0]);
    }
}
